  ui_story_31380601_64_dialog_content = "¿Es esto? La puerta está abierta—",
  ui_story_31380601_65_dialog_content = "¿Ah?",
  ui_story_31380601_66_dialog_content = "PlayerName, usted vino.",
  ui_story_31380601_67_dialog_content = "Ah... ¿S-Siobhan?",
  ui_story_31380601_68_dialog_content = "¿Qué pasa? ¿No crees que me veo fabulosa?",
  ui_story_31380601_69_dialog_content = "Te ves tan hermosa que por un momento ahí sentí que mi alma me abandonaba.",
  ui_story_31380601_70_dialog_content = "¿En serio? ¡Gracias!",
  ui_story_31380601_71_dialog_content = "Mientras creas que me veo bien, sé que no tengo nada de qué preocuparme.",
  ui_story_31380601_72_dialog_content = "Pero eso no significa que pueda volverme complaciente.",
  ui_story_31380601_73_dialog_content = "Le pedí que viniera porque esperaba que pudiera brindarme su análisis honesto desde un punto de vista racional, neutral y objetivo.",
  ui_story_31380601_74_dialog_content = "¿Análisis? ¡Es solo un concurso de canto, para gritar en voz alta!",
  ui_story_31380601_75_dialog_content = "Como académico serio, necesito canalizar el espíritu de investigación incluso cuando participo en un concurso de canto.",
  ui_story_31380601_76_dialog_content = "Incluso escribí una tesis para este concurso.",
  ui_story_31380601_77_dialog_content = "Es un análisis de varios factores que afectan el resultado de la competencia, desde el escenario hasta el sistema de competencia, los participantes y otros aspectos.",
  ui_story_31380601_78_dialog_content = "Comencemos con el escenario—",
  ui_story_31380601_79_dialog_content = "Este es un escenario al aire libre, por lo que el rendimiento se verá muy afectado por el clima.",
  ui_story_31380601_80_dialog_content = "Si hace viento o llueve, eso podría estropear el rendimiento.",
  ui_story_31380601_81_dialog_content = "Por lo tanto, durante la actuación, debemos considerar completamente el impacto potencial de varias condiciones climáticas.",
  ui_story_31380601_82_dialog_content = "A continuación, hablemos del sistema de competencia:",
  ui_story_31380601_83_dialog_content = "Lo primero a considerar es la audición en sí, que se puede decir que es la fase más difícil.",
  ui_story_31380601_84_dialog_content = "Si se comete un solo error durante esta fase, los participantes se enfrentarán a la eliminación y no tendrán más oportunidades de continuar participando.",
  ui_story_31380601_85_dialog_content = "Además, muchos de los participantes ya han acumulado un cierto grado de popularidad y una base de fans considerable antes del inicio de la competencia.",
  ui_story_31380601_86_dialog_content = "Disfrutarán de una mayor ventaja en la competencia.",
  ui_story_31380601_87_dialog_content = "Entonces, ¡lo más importante aquí es analizar a los participantes!",
  ui_story_31380601_88_dialog_content = "Esta tabla muestra un \"análisis de clasificación de ídolos\" para mis oponentes y para mí.",
  ui_story_31380601_89_dialog_content = "Incluye canto, baile, apariencia, figura, EQ e IQ, con una puntuación máxima de 5 para cada categoría.",
  ui_story_31380601_90_dialog_content = "Caronte—",
  ui_story_31380601_91_dialog_content = "Cantar—5, bailar—5, apariencia—4, figura—4, EQ—0, IQ—3.",
  ui_story_31380601_92_dialog_content = "Un candidato popular para ocupar el primer puesto de esta competencia.",
  ui_story_31380601_93_dialog_content = "El metal gótico agita el corazón como una ola embravecida.",
  ui_story_31380601_94_dialog_content = "Tiene suficiente ventaja para asustar a sus oponentes.",
  ui_story_31380601_95_dialog_content = "Su debilidad es que su EQ bajo no lo llevará muy lejos.",
  ui_story_31380601_96_dialog_content = "liliam—",
  ui_story_31380601_97_dialog_content = "Cantar: 2, bailar: 2, apariencia: 4, figura: 3, EQ: 1, IQ: 5.",
  ui_story_31380601_98_dialog_content = "Producto de la nueva generación, poseen cierta novedad en el sentido de que van en contra de la lógica convencional.",
  ui_story_31380601_99_dialog_content = "La gloria y la dignidad de cuatro personas (máquinas) poniendo todo en juego para despertar su cuerpo principal...",
  ui_story_31380601_100_dialog_content = "Su debilidad es que son descaradamente demasiado robóticos.",
  ui_story_31380601_101_dialog_content = "Aunque algunas personas están locas por este tipo de competidor, no tienen lo necesario para ganarse al público en general.",
  ui_story_31380601_102_dialog_content = "Tu análisis es tan detallado... Nunca hubiera imaginado que eras nuevo en este tipo de cosas.",
  ui_story_31380601_103_dialog_content = "No lo olvides, ¡soy un investigador profesional!",
  ui_story_31380601_104_dialog_content = "Pero, ¿de dónde sacaste toda esa información sobre tus competidores?",
  ui_story_31380601_105_dialog_content = "Bueno, invité al personal de registro a tomar algo.",
  ui_story_31380601_106_dialog_content = "Terminaron diciéndome todo. Incluso me sorprendió la cantidad de información que me dieron.",
  ui_story_31380601_107_dialog_content = "No había planeado investigar esto tan a fondo...",
  ui_story_31380601_108_dialog_content = "¿Les diste una gotita de tu bebida favorita para aflojar los labios?",
  ui_story_31380601_109_dialog_content = "Bueno, no me metí en ningún asunto personal. Solo registré información relacionada con la competencia.",
  ui_story_31380601_110_dialog_content = "Menos mal que fuiste tú quien descubrió todo esto. Si alguien más tuviera en sus manos esta información, podría significar malas noticias para los demás participantes.",
  ui_story_31380601_111_dialog_content = "No importa eso, sigamos inspeccionando los datos de la competencia.",
  ui_story_31380601_112_dialog_content = "Te presenté un montón de competidores hace un momento, pero el más formidable es el siguiente:",
  ui_story_31380601_113_dialog_content = "¡El último y más fuerte guerrero de la familia Sakura!",
  ui_story_31380601_114_dialog_content = "Hiiro!",
  ui_story_31380601_115_dialog_content = "Su calificación específica no se puede calcular en este momento, pero puede estar seguro de que sus estadísticas están fuera de serie.",
  ui_story_31380601_116_dialog_content = "El ganador de la competencia del año pasado, Hiiro, es un oponente asombrosamente fuerte.",
  ui_story_31380601_117_dialog_content = "Tan sublime como una flor de cerezo flotante y tan feroz como un dragón rugiente.",
  ui_story_31380601_118_dialog_content = "No estoy seguro de si hay un Aurorian vivo que pueda vencerla.",
  ui_story_31380601_119_dialog_content = "¡Nunca me di cuenta de que Hiiro era tan impresionante!",
  ui_story_31380601_120_dialog_content = "¿Entonces qué vas a hacer? ¿Vas a intentar derrotar a Hiiro?",
  ui_story_31380601_121_dialog_content = "Bueno, en cuanto a mí, Siobhan...",
  ui_story_31380601_122_dialog_content = "Cantar: 1, bailar: 1, apariencia: 6, figura: 6, EQ: 5, IQ: 5.",
  ui_story_31380601_123_dialog_content = "Esperar. ¿Le dieron a su apariencia y figura 6 puntos cada uno?",
  ui_story_31380601_124_dialog_content = "¡Pensé que habías dicho que el máximo eran cinco puntos!",
  ui_story_31380601_125_dialog_content = "*Tos* Aunque no soy bueno cantando o bailando, las otras cuatro áreas deberían compensar eso.",
  ui_story_31380601_126_dialog_content = "¿Estás fingiendo que no puedes oírme?",
  ui_story_31380601_127_dialog_content = "No importa, esos dos puntajes son objetivos de todos modos.",
  ui_story_31380601_128_dialog_content = "¡Hah!",
  ui_story_31380601_129_dialog_content = "¿Te estas riendo?",
  ui_story_31380601_130_dialog_content = "De todos modos... si lo doy todo, tendré la oportunidad de ganar todo esto.",
  ui_story_31380601_131_dialog_content = "Pero fuiste un poco duro contigo mismo en las categorías de canto y baile... ¿Solo diste un punto por cada uno?",
  ui_story_31380601_132_dialog_content = "¿Crees que te has preparado lo suficientemente bien como para estar entre los tres primeros?",
  ui_story_31380601_133_dialog_content = "Esa es otra razón por la que te invité aquí. No hay forma de que mi evaluación de mí mismo pueda ser lo suficientemente objetiva.",
  ui_story_31380601_134_dialog_content = "¿Por qué no me muestras parte de tu actuación y me dejas darte una puntuación?",
  ui_story_31380601_135_dialog_content = "¿Quieres que actúe ahora? Es tan repentino... Para ser honesto, me siento un poco tímido.",
  ui_story_31380601_136_dialog_content = "Pero si eso es lo que quieres...",
  ui_story_31380601_137_dialog_content = "Bien, hagamos esto.",
  ui_story_31380601_138_dialog_content = "(Hmm... Sé que esto es solo la apertura de su actuación, pero el estilo de Siobhan no está nada mal).",
  ui_story_31380601_139_dialog_content = "(Pasos ligeros, una postura hermosa, un rostro hermoso: tiene buenas posibilidades de cautivar a la mayoría de las personas en la audiencia).",
  ui_story_31380601_140_dialog_content = "♪ Ir a trabajar cuando me despierto, no tengo tiempo para comer ♪",
  ui_story_31380601_141_dialog_content = "♪ Demasiado trabajo que manejar, no tengo tiempo para dormir ♪",
  ui_story_31380601_142_dialog_content = "Espera, ¿¡qué clase de canción es esta!?",
  ui_story_31380601_143_dialog_content = "Elegí una canción de rap al azar de las listas de éxitos anteriores.",
  ui_story_31380601_144_dialog_content = "Pensé que era algún tipo de heavy metal...",
  ui_story_31380601_145_dialog_content = "A juzgar por tu expresión, supongo que no soy tan bueno como solía ser.",
  ui_story_31380601_146_dialog_content = "¿Has actuado en el escenario antes?",
  ui_story_31380601_147_dialog_content = "Cuando era muy joven y vivía en Entrañas 66, bailé en algunas presentaciones grupales.",
  ui_story_31380601_148_dialog_content = "¿¡Cuando eras muy joven!?",
  ui_story_31380601_149_dialog_content = "Solo tenía cuatro o cinco años, pero todavía dirigía la compañía.",
  ui_story_31380601_150_dialog_content = "Creo que podría haber sacado al menos un cuatro en canto y baile en ese entonces.",
  ui_story_31380601_151_dialog_content = "Pero, considerando el hecho de que no he practicado en años, asumí que mis habilidades se habrían deteriorado significativamente, así que le di un puntaje objetivo de un punto.",
  ui_story_31380601_152_dialog_content = "Tu evaluación de ti mismo es en realidad muy racional, neutral y objetiva.",
  ui_story_31380601_153_dialog_content = "Ahora parece que será difícil ganar solo cantando y bailando.",
  ui_story_31380601_154_dialog_content = "Entonces, ¿crees que debería agregar algunos de mis talentos personales a mi número de canto y baile?",
  ui_story_31380601_155_dialog_content = "¿Qué tipo de talentos personales?",
  ui_story_31380601_156_dialog_content = "Demolición-",
  ui_story_31380601_157_dialog_content = "Haré una pequeña bomba de humo que emita una gran explosión rugiente...",
  ui_story_31380601_158_dialog_content = "Luego saldré del humo y le daré al público una agradable sorpresa.",
  ui_story_31380601_159_dialog_content = "(No sé si el escenario podría soportar una explosión... Si se derrumba, ciertamente sería una sorpresa).",
  ui_story_31380601_160_dialog_content = "Camuflaje avanzado—",
  ui_story_31380601_161_dialog_content = "Me esconderé entre la decoración y seguiré cantando: \"Siobhan es la mejor\", para lavarles el cerebro a los transeúntes.",
  ui_story_31380601_162_dialog_content = "(¿Es tan fácil lavarle el cerebro a la gente?)",
  ui_story_31380601_163_dialog_content = "Danza de la Araña—",
  ui_story_31380601_164_dialog_content = "Haré que mis adorables arañas tejan telarañas por el escenario, y cada pequeña araña saltará al ritmo de la música.",
  ui_story_31380601_165_dialog_content = "También pueden deambular entre la audiencia para interactuar con las personas. A todos les encantaría eso, ¿verdad?",
  ui_story_31380601_166_dialog_content = "(Y si un miembro de la audiencia sufre de aracnofobia, se desmayará en el acto...)",
  ui_story_31380601_167_dialog_content = "Y el último es el polvo de precisión.",
  ui_story_31380601_168_dialog_content = "Si todo lo demás falla, ¡todavía tengo este as bajo la manga!",
  ui_story_31380601_169_dialog_content = "He estado quitando el polvo de las antigüedades durante muchos años y he dominado la habilidad única de quitar el polvo.",
  ui_story_31380601_170_dialog_content = "Si desempolvo a toda la audiencia, estarán complacidos conmigo, ¿no?",
  ui_story_31380601_171_dialog_content = "(Cuando de repente comienzas a invadir el espacio personal de todos con tu plumero, ¿quién estaría complacido con eso?)",
  ui_story_31380601_172_dialog_content = "¡Me estoy poniendo todo nervioso! ¿Qué habilidad debo usar?",
  ui_story_31380601_173_dialog_content = "PlayerName, ¿me pueden ayudar a elegir uno?",
  ui_story_31380601_174_option_content = "¿Puedo elegir ninguno de ellos?",
  ui_story_31380601_175_dialog_content = "¿Realmente no son aptos para la competición?",
  ui_story_31380601_176_dialog_content = "(La cabeza de Siobhan cuelga tan baja... Parece realmente desesperanzada.)",
  ui_story_31380601_177_dialog_content = "Tus habilidades son geniales, pero no son adecuadas para una actuación como esta.",
  ui_story_31380601_178_dialog_content = "Gracias por su franqueza... y por su amabilidad.",
  ui_story_31380601_179_option_content = "¡Solo elige el que más te guste!",
  ui_story_31380601_180_dialog_content = "Crees que todos son buenos, ¿verdad...? Entonces, ¿es difícil hacer una elección...?",
  ui_story_31380601_181_dialog_content = "Luego los usaré todos para maximizar mis posibilidades de ganar.",
  ui_story_31380601_182_dialog_content = "(Espero que no salga nada malo de esto).",
  ui_story_31380601_183_dialog_content = "Realmente te hice pasar por mucho hoy.",
  ui_story_31380601_184_dialog_content = "Está bien. De hecho, obtuve mucha información hoy...",
  ui_story_31380601_185_dialog_content = "¡Ahora, voy a hacer todo lo posible para prepararme para mi audición!",
  ui_story_31380601_186_dialog_content = "¡Buena suerte!"
}
return config
